INSERT INTO algo_ai_analysis (scene, context, question, answer, reasoning, source, latency_ms, actor_did, evidence_id, created_at) VALUES
  ('dispatch', '{"taskId": "dp-000001"}', '为什么选择节点C放电？', '节点C当前负荷150kW为全网最高，SOC 42% 仍有放电裕度，放电24kW的边际收益最大。', '["总负荷450kW高于总光伏145kW，存在缺口", "节点C负荷占比33%为最高", "节点C SOC 42% 高于下限20%"]', 'cache', 1240, 'did:vpp:user:0x34ba9ca061137b9b46fc73d103be8f98', NULL, '2026-08-17 01:00:00'),
  ('risk', '{"nodeId": "Node-A"}', '当前隐私风险主要来自哪里？', '主要风险来自查询频率过高与数据粒度过细的叠加效应，建议收紧差分隐私预算。', '["5分钟内12次查询，超出基线3倍", "分钟级粒度可反推用能行为", "暴露字段6个含地理位置"]', 'cache', 980, 'did:vpp:user:0x34ba9ca061137b9b46fc73d103be8f98', NULL, '2026-08-17 01:11:00'),
  ('audit', '{"period": "day"}', '今日审计有什么异常？', '今日出现1次越权访问告警与1次异常DID接入尝试，均已拦截并留痕。', '["R01越权访问命中3次", "R02异常DID接入1次", "全部高危操作已上链"]', 'rule', 12, 'did:vpp:user:0x34ba9ca061137b9b46fc73d103be8f98', NULL, '2026-08-17 01:22:00'),
  ('data', '{"assetId": 1001}', '这条数据的敏感等级为什么是L3？', '该资产包含地理位置字段且采集粒度为分钟级，可关联到具体用能主体，判定为敏感级。', '["含location字段", "采集粒度1min", "可关联主体身份"]', 'cache', 1105, 'did:vpp:user:0x34ba9ca061137b9b46fc73d103be8f98', NULL, '2026-08-17 01:33:00'),
  ('qa', '{}', '什么是可信数据空间？', '可信数据空间是在数据不出域前提下，通过可信身份、可信存证与细粒度授权实现数据要素安全流通的基础设施。', '["身份可信", "过程可溯", "权限可控"]', 'cache', 1520, 'did:vpp:user:0x34ba9ca061137b9b46fc73d103be8f98', NULL, '2026-08-17 01:44:00');
